name: Auto-close PRs targeting unready issues
on:
  pull_request:
    types: [opened, edited, synchronize]

jobs:
  check-pr:
    runs-on: ubuntu-latest
    steps:
      - name: Check for unready issues
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.pull_request.number
            });

            // Skip if PR is from a maintainer or bot
            const author = pr.user.login;
            if (author.includes('[bot]') || author === 'mlflow-automation' || author === 'mlflow-bot') {
              console.log('Skipping bot or maintainer PR');
              return;
            }

            // Parse issue references from PR body
            const issueRegex = /#(\d+)|https?:\/\/github\.com\/[^\/]+\/[^\/]+\/issues\/(\d+)/g;
            const matches = [];
            let match;
            while ((match = issueRegex.exec(pr.body)) !== null) {
              matches.push(match[1] || match[2]);
            }

            // Skip if multiple issues referenced
            if (matches.length > 1) {
              console.log('Skipping PR with multiple issue references');
              return;
            }

            // Skip if no issues referenced
            if (matches.length === 0) {
              console.log('No issue references found');
              return;
            }

            const issueNumber = parseInt(matches[0]);

            // Get issue details
            const { data: issue } = await github.rest.issues.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issueNumber
            });

            // Skip issues created before 2026-03-10
            const creationDate = new Date(issue.created_at);
            const cutoffDate = new Date('2026-03-10');
            if (creationDate < cutoffDate) {
              console.log(`Skipping issue created before cutoff date: ${issue.created_at}`);
              return;
            }

            // Check if issue has 'ready' label
            const hasReadyLabel = issue.labels.some(label => label.name === 'ready');

            if (!hasReadyLabel) {
              console.log(`Issue #${issueNumber} does not have 'ready' label`);

              // Close the PR with a friendly comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.pull_request.number,
                body: `This PR references issue #${issueNumber}, which hasn't been triaged yet (missing the \`ready\` label). Please ensure the referenced issue is properly labeled before this PR can be considered for merging.\n\nThis PR will be closed automatically as it cannot proceed until the referenced issue is ready.`
              });

              await github.rest.pulls.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: context.payload.pull_request.number,
                state: 'closed'
              });

              console.log(`Closed PR #${context.payload.pull_request.number} due to unready issue #${issueNumber}`);
            } else {
              console.log(`Issue #${issueNumber} has 'ready' label, PR remains open`);
            }
